// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Errors".

The error in this rendering is the attempt to create a structure
inside the cube. This attempt never succeeds. The scene is
rendered twice to simulate the cube's transparency.

I tried to reproduce a bit of the style of anime from the
mid-1970s and early 1980s, like, for instance,
Space Battleship Yamato and Macross.
*/

let theShader, moves=[0,0], dpr = Math.max(1, 0.75 * window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return;
	moves[0] += (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	moves[1] += (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
}

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2651488/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  shader(theShader);
	mouseMove();
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
	theShader.setUniform("move", moves);
  theShader.setUniform("pointerCount", ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) ? 1 : 0);
	theShader.setUniform("startRandom", startRandom); // each time the shader starts, make it unique
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; 
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
uniform int pointerCount;
uniform float startRandom;
#define P pointerCount
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+15.+15.*startRandom)
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(6.3*(a)+vec3(1,2,3)))
// Returns a pseudo random number for a given scalar (white noise)
float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return p.x*p.y;
}
// Returns a value interpolated between two random values at a given point t with an exponent e
float curve(float t, float e) {
	t/=e;
	return mix(
		rnd(floor(t)),
		rnd(floor(t)+1.),
		pow(S(.0,1.,t),10.)
	);
}
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f);
	float
	a=rnd(i),
	b=rnd(i+vec2(1,0)),
	c=rnd(i+vec2(0,1)),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
	float t=.0, a=1., h=.0; mat2 m=mat2(1.5,-.6,.6,1.4);
	for (float i=.0; i<5.; i++) {
		t+=a*noise(p*m);
		a*=.5;
		p*=2.*m;
		h+=a;
	}
	return t/h;
}
// Returns a 2d point on a sphere for a given 3d point
vec2 sm(vec3 p) {
	p.yz*=rot(-.57);
	p.xz*=rot(1.57);
	return .5+vec2(atan(p.x,p.z),atan(p.y,length(p.xz)))/6.28318;
}
// Creates a cloud pattern for a sphere
float pattern(vec3 p) {
	p.xz*=rot(2.);
	vec2 uv=sm(p.zyx*.2);
	return S(1.,.0,abs(p.y))*noise(.5-uv+fbm(uv*20.));
}
// Smooth min for scalars
// which can be used as smooth union
// by making b and k negative.
float smin(float a, float b, float k) {
	float h = clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
// Signed distance function of a box with dimension 's' and corner radius 'r'
float box(vec3 p, vec3 s, float r) {
	p=abs(p)-s-r;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z))-r;
}
// Signed distance function of a menger sponge with dimension 's', corner radius 'r' and level 'l'
float mspo(vec3 p, vec3 s, float r, float l) {
	const float k=.25;
	float
	d=box(p,s,r),
	res=d,
	f=1.,
	i=.0;
	for(; i++<l;) {
		vec3
		a=mod(p*f,2.)-1.,
		r=abs(1.-3.*abs(a));
		f*=3.;
		float
		da=max(r.x,r.y),
		db=max(r.y,r.z),
		dc=max(r.z,r.x),
		c=(smin(da,smin(db,dc,k),k)-.75)/f;
		if(c>d) d=c, res = c;
	}
	return res;
}
// Signed distance function of a box frame width dimension 's' and thickness 'e'
float frame(vec3 p, vec3 s, float e) {
	p=abs(p)-s;
	vec3 q=abs(p+e)-e;
	return min(min(
		length(max(vec3(p.x,q.y,q.z),.0))+min(max(p.x,max(q.y,q.z)),.0),
		length(max(vec3(q.x,p.y,q.z),.0))+min(max(q.x,max(p.y,q.z)),.0)),
		length(max(vec3(q.x,q.y,p.z),.0))+min(max(q.x,max(q.y,p.z)),.0));
}
// Mapping function of the outer shell which is a cube
float mapCube(vec3 p) {
	return box(p,vec3(1),.005);
}
// Mapping function of the inner geometries
float mapInner(vec3 p) {
	float t=curve(T*4.,.4);
	return min(frame(p,vec3(1),.05),mspo(p,vec3(.7),mod(t*4.,4.)*.025,mod(t*4.,4.)));
}
// Returns the normal vector of a given point on the outer cube
vec3 normCube(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*mapCube(p+k.xyy*h)+
		k.yxy*mapCube(p+k.yxy*h)+
		k.yyx*mapCube(p+k.yyx*h)+
		k.xxx*mapCube(p+k.xxx*h)
	);
}
// Returnd the normal vector of a given point on the inner geometry
vec3 normInner(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*mapInner(p+k.xyy*h)+
		k.yxy*mapInner(p+k.yxy*h)+
		k.yyx*mapInner(p+k.yyx*h)+
		k.xxx*mapInner(p+k.xxx*h)
	);
}
// Raymarcher
float march(inout vec3 p, vec3 rd, bool inner) {
	float dd=.0;
	for (float i=.0; i<400.; i++) {
		float d=inner?mapInner(p):mapCube(p);
		if (abs(d)<1e-3 || d>10.) break;
		p+=rd*d;
		dd+=d;
	}
	return dd;
}
// Returns the shadow value of the given point with the given light position
float shadow(vec3 p, vec3 lp) {
	float shd=1., maxd=length(lp-p);
	vec3 l=normalize(lp-p);
	for (float i=1e-3; i<maxd;) {
		float d=mapInner(p+l*i);
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd,128.*d/i);
		i+=d;
	}
	return shd;
}
// Returns the amount of ambient occlusion at the given point
float calcAO(vec3 p, vec3 n) {
	float occ=.0, sca=1.;
	for (float i=.0; i<5.; i++) {
		float
		h=.01+i*.09,
		d=mapInner(p+h*n);
		occ+=(h-d)*sca;
		sca*=.55;
		if (occ>.35) break;
	}
	return clamp(1.-3.*occ,.0,1.)*(.5+.5*n.y);
}
// Calculates the sub surface scattering at a given point along the ray direction with distance and strength
float getsss(vec3 p, vec3 rd, float dist, float k) {
  float ddist = dist*k;
  return
  clamp(mapCube(p+rd*dist)/dist,.0, 1.)+
  clamp(mapCube(p+rd*ddist)/ddist,.0, 1.);
}
// Position and animate the camera
void cam(inout vec3 p) {
	float t=curve(T*.1,.8)+T*.1;
	p.yz*=rot(-.42-move.y*6.3/MN+(P>0?.0:t));
	p.xz*=rot(-move.x*6.3/MN+(P>0?.0:t));
}
// The main function of the fragment shader
void main() {
	// calculate the unit vector (center between -.5 and .5)
	vec2 uv=(FC-.5*R)/MN;
	// adjust to whole pixels
	uv=floor(uv*MN)/MN;
	// initialize the color vector
	vec3 col=vec3(0),
	// position the camera
	p=vec3(0,0,-4),
	// calculate the frustum (which is the ray direction)
	rd=N(vec3(uv,1)),
	// position the light source
	lp=vec3(0,3,-3);
	// adjust and animate the camera
	cam(p); cam(rd); cam(lp);
	// initial time to reveal the scene
	float t=min((time-.5)*.3,1.),
	// march the outer shell
	d=march(p,rd,false);
	if (d<10.) {
		// outer shell hit
		// calculate the normal vector of the outer shell and the light vector
		vec3 n=normCube(p); vec3 l=N(lp-p);
		// calculate the diffuse light for the outer shell
		float dif=clamp(dot(l,n),.0,1.),
		// calculate the fresnel value for the outer shell
		fres=pow(clamp(1.+dot(rd,n),.0,1.),5.),
		// calculate the specular light for the outer shell
		spk=pow(clamp(dot(reflect(rd,n),l),.0,1.),64.),
		// calculate the sub surface scattering of the outer shell
		// and save the outer shell's fresnel value for later use
		sss=getsss(p,rd,5.,3.), fr=fres;
		// lighten the center of the face
		col+=sqrt(dif)*1./max(5e-2,length(p));
		// darken the edges of the face
		col=mix(col*vec3(.6,.8,1),vec3(0),fres);
		// add cubemap reflections (but not to the occluded areas)
		col=mix(col,2.*mix(vec3(.8,.95,1),vec3(.08,.08,.1),pattern(N(reflect(rd,n)))),sqrt(fres));
		// add a specular reflection
		// first with a color gradient
		col+=spk*.75*hue(.2+spk/2.)*abs(n);
		// then with bright white light
		col+=spk*.5;
		// calculate the refraction value of the outer shell
		rd=refract(rd,n,.7);
		// march the inner geometries of the scene
		float dd=march(p,rd+n*sin(dot(p,p)*11.)*.02,true);
		if (dd<10.) {
			// inner geometries are hit
			// calculate the normal vector of the inner geometries and the light vector
			n=normInner(p); l=N(lp-p);
			// calculate the diffuse light for the inner geometries and the fresnel value
			dif=clamp(dot(l,n),.0,1.), fres=pow(clamp(dot(rd,n),.0,1.),5.);
			// calculate the shadows and ambient occlusion of the inner geometries
			float shd=shadow(p+n*5e-2,lp), ao=calcAO(p,rd);
			// apply lights and shadows to a new material
			vec3 mat=mix(vec3(.08),vec3(dif*shd),1.-ao);
			// colorize the new material
			mat=mix(mat*vec3(1,.2,.1),vec3(0),fres);
			// mix in the inner geometries according to fresnel and sub surface scattering
			col=mix(col,mat,.4-fr/sss);
			// increase the luminance of the scene
			col*=1.5;
			// increase the contrast of the scene
			col=S(.0,1.,col);
		} 
		// darken the scene
		col=S(.0,1.2,col);
		// increase the shadows and darken the colors
		col=tanh(col*col*col);
	} else {
		// add a color gradient to the background
		col=mix(vec3(.3,.8,.7),vec3(0,0,.1),sqrt(dot(hue(S(1.,-2.,length(uv))),vec3(.21,.71,.07))));
		// color grade the background
		col=tanh(col*col);
	}
	// initial revelation of the scene
	col=mix(vec3(0),col,t);
	// color grade the scene
	col=pow(col,vec3(.4545));
	// lift the darkest black
	col=max(col,.08);
	// output the scene's color
	O=vec4(col,1);
}

